rawInput.command:
$root = "C:\Users\magicvr\Documents\Code\goal-governance"
$gov = Join-Path $root "docs"
$wsRoot = Join-Path $gov "workspaces"
Write-Output "=== canonical workspace.md ==="
if (Test-Path -LiteralPath $wsRoot) {
  Get-ChildItem -LiteralPath $wsRoot -Directory -Force | ForEach-Object {
    $wm = Join-Path $_.FullName "workspace.md"
    $isLink = ($_.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0
    $resolved = (Resolve-Path -LiteralPath $_.FullName).Path
    $rel = [IO.Path]::GetRelativePath((Resolve-Path -LiteralPath $root).Path, $resolved)
    "{0}`texists_wm={1}`tlink={2}`trel={3}" -f $_.Name, (Test-Path -LiteralPath $wm), $isLink, $rel
  }
} else { Write-Output "NO workspaces dir" }
Write-Output "=== old direct workspace-* under docs ==="
Get-ChildItem -LiteralPath $gov -Directory -Force | Where-Object { $_.Name -like "workspace-*" } | ForEach-Object {
  $wm = Join-Path $_.FullName "workspace.md"
  "{0}`texists_wm={1}" -f $_.Name, (Test-Path -LiteralPath $wm)
}
Write-Output "=== docs/goals ==="
Write-Output ("goals_exists=" + (Test-Path -LiteralPath (Join-Path $gov "goals")))
Write-Output "=== GOAL-018 dirs under canonical workspaces ==="
Get-ChildItem -LiteralPath $wsRoot -Directory -Force | ForEach-Object {
  $hits = Get-ChildItem -LiteralPath $_.FullName -Directory -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -like "GOAL-018-*" -or $_.Name -eq "GOAL-018" }
  foreach ($h in $hits) { "{0}\{1}" -f $_.Name, $h.Name }
}

